    if (s2 && skills[1]) { refreshSelects(); s2.value = skills[1]; }
    if (s3 && skills[2]) { refreshSelects(); s3.value = skills[2]; }
    refreshSelects();
    updateSkillValue();
  }

  // Preset proficiency strings must survive the same native cap as restored slots.
  同步自得熟练度();刷新武学熟练度();
  const presetProfs=Array.isArray(p.profs)?p.profs:String(p.profs||'').split('、');
  const presetRows=document.querySelectorAll('#custom-skills .custom-skill-row');
  presetProfs.forEach((value,i)=>{const el=isCustom?presetRows[i]?.querySelector('.cs-prof'):document.getElementById('prof-'+(i+1));if(el&&Array.from(el.options).some(op=>op.value===value&&!op.disabled))el.value=value;});
  // 高亮提示玩家填写
  ['n','age','nick','look'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) { el.style.borderColor = '#a81c1c'; el.placeholder = '← 请填写'; }
  });
}

