/* ═══════════ [v3.1] 武学熟练度（口径：《世界观/武学熟练度》） ═══════════ */
const 熟练度表 = [
  { 名: '皮毛', 述: '初识门径；使用本档已定义的招式与词条' },
  { 名: '粗通', 述: '招式渐熟；开放本档已定义的招式与词条' },
