/* ═══════════ [v3.1] 联动挂载 ═══════════ */
(function 挂载新增栏() {
  try {
    const 原刷新 = window.refreshSelects;
    window.refreshSelects = function () { if (原刷新) 原刷新.apply(this, arguments); 刷新武学熟练度(); };
    // 自得武学：新增行 / AI 生成 / 启卷 三条路都要重算熟练度锁死
    const 包一层 = function (名, 同步前) {
      const 原 = window[名];
      if (!原) return;
      window[名] = function () {
        if (同步前) 同步自得熟练度();
        const r = 原.apply(this, arguments);
        if (!同步前) 同步自得熟练度();
        return r;
      };
    };
    包一层('addCustomSkill', false);
    包一层('fillCustomSkills', false);
    包一层('applyDataToForm', false);
    包一层('loadFromSlot', false);
    // 容器级事件委托：品级变化即时重算（行会被重建，故监听容器而非行）
    const 箱 = document.getElementById('custom-skills');
    if (箱) {
      箱.addEventListener('change', function (e) {
        const el = e.target;
        if (!el) return;
        if (el.classList && el.classList.contains('cs-grade')) 同步自得熟练度();
        else if (el.classList && el.classList.contains('cs-prof')) 刷新武学熟练度();
      });
      if (typeof MutationObserver !== 'undefined') {
        // 只观察直接子节点（增删行），不观察子树，避免"填下拉→触发观察→再填"的循环
        new MutationObserver(function () { 同步自得熟练度(); }).observe(箱, { childList: true });
      }
    }
    [1, 2, 3].forEach(function (i) {
      const sk = document.getElementById('skill-' + i);
      if (sk) sk.addEventListener('change', 刷新武学熟练度);
    });
    const lvl = document.getElementById('level');
    if (lvl) lvl.addEventListener('change', function () { if (window.refreshSelects) window.refreshSelects(); else 刷新武学熟练度(); 同步自得熟练度(); });
    /* 默认不预置百艺：可留空（提交时记为「未修百艺」），需要时点「添加」自行增添 */
    刷新武学熟练度();
    同步自得熟练度();
  } catch (e) { console.error('新增栏挂载失败', e); }
})();

