function doneFail(msg) { alert(msg); }
function parseSkillBlock(text) {
  if (!text) return [];
  // 1) JSON 优先：提取最外层数组/对象
  const arrM = text.match(/\[[\s\S]*\]/);
  if (arrM) {
    try {
      const arr = JSON.parse(arrM[0]);
      if (Array.isArray(arr)) {
        return arr.map(function (o) {
          return {
            name: String(o.name || o.名称 || '').trim(),
            grade: String(o.grade || o.品级 || '三品').trim(),
            type: 规范武学类型(o.type || o.类型 || '内功', String(o.name || o.名称 || '').trim()),
            desc: String(o.desc || o.描述 || '').trim()
          };
        }).filter(function (s) { return s.name; });
      }
    } catch (e) {}
    try {
      const obj = JSON.parse(arrM[0]);
      if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
        const s = { name: String(obj.name || obj.名称 || '').trim(), grade: String(obj.grade || obj.品级 || '三品').trim(), type: 规范武学类型(obj.type || obj.类型 || '内功', String(obj.name || obj.名称 || '').trim()), desc: String(obj.desc || obj.描述 || '').trim() };
        return s.name ? [s] : [];
      }
    } catch (e) {}
  }
  // 2) 文本格式回退：按「名称：」切分（开头或换行后皆可）
  const parts = text.split(/(?:^|\n)\s*名称[：:]\s*/).filter(function (x) { return x && x.trim(); });
  const skills = [];
  for (const p of parts) {
    const lines = p.split(/\n/);
    const name = lines[0].replace(/^[\s\d、.．#*\-]+/, '').trim();
    const grade = (p.match(/品级[：:]\s*([^\n]+)/) || [])[1];
    const type = (p.match(/类型[：:]\s*([^\n]+)/) || [])[1];
    const desc = (p.match(/描述[：:]\s*([\s\S]+)$/) || [])[1];
    if (!name || (!grade && !type)) continue;
    skills.push({ name: name, grade: grade ? grade.trim() : '三品', type: type ? type.trim() : '内功', desc: desc ? desc.trim() : '' });
  }
  return skills;
}
