    <script>
        /* IIFE 作用域隔离：防止多个美化并存时同名函数互相覆盖 */
        (function() {
        /* ========== 获取消息内容（宽容：API 失败不崩溃） ========== */
        function getMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (chatMessages && chatMessages.length > 0) {
                    return chatMessages[0].message;
                }
            } catch (e) {
                console.error("获取消息API失败", e);
            }
            return null;
        }

        /* ========== 终极宽容解析（不依赖标签完整性，支持全角符号） ========== */
        function parseData(messageText) {
            var result = {};

            /* 优先在 <martial_arts_book> 标签内提取；标签缺失则全文兜底 */
            var scope = messageText;
            var tagMatch = messageText.match(/<martial_arts_book>([\s\S]*?)<\/martial_arts_book>/);
            if (tagMatch && tagMatch[1]) {
                scope = tagMatch[1];
            }

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            /* 按关键词匹配：支持 [武学名称|xx] / 武学名称：xx / 武学名称:xx */
            function extractValue(keyword) {
                var reg = new RegExp(keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || messageText.match(reg);
                if (match && match[1]) {
                    var val = match[1].trim();
                    return val.replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var kw_title = extractValue('武学名称');
            var kw_category = extractValue('武学类别');
            var kw_rank = extractValue('评级');
            var kw_prof = extractValue('熟练度');
            var kw_effect = extractValue('特殊效果');
            var kw_origin = extractValue('渊源');

            if (kw_title || kw_category || kw_effect || kw_rank || kw_prof || kw_origin) {
                if (kw_title) result['武学名称'] = kw_title;
                if (kw_category) result['武学类别'] = kw_category;
                if (kw_rank) result['评级'] = kw_rank;
