            } catch (e) {
                console.error("获取消息API失败", e);
            }
            return null;
        }

        /* ========== 终极宽容解析（不依赖 <baiyi_panel> 标签） ========== */
        function parseData(messageText) {
            var result = {
                '百艺名称': '',
                '百艺图标': '',
                '境界': '',
                '行为': '',
                '点评': '',
                '效果': ''
            };

            /* 优先在 <baiyi_panel> 标签内提取，避免与同消息其他美化(如武功秘籍)串数据 */
            var scope = messageText;
            var tagMatch = messageText.match(/<baiyi_panel>([\s\S]*?)<\/baiyi_panel>/);
            if (tagMatch && tagMatch[1]) scope = tagMatch[1];
            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            /* 按关键词匹配：支持 [百艺名称|琴] / 百艺名称：琴 / 百艺名称:琴 */
            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    var val = match[1].trim();
                    return val.replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var kw_name = extractValue('百艺名称');
            var kw_icon = extractValue('百艺图标');
            var kw_rank = extractValue('造诣');
            var kw_act = extractValue('所作');
            var kw_quote = extractValue('风评');
            var kw_effect = extractValue('见效');

            if (kw_name || kw_act || kw_effect) {
                result['百艺名称'] = kw_name || result['百艺名称'];
                result['百艺图标'] = kw_icon || result['百艺图标'];
                result['造诣'] = kw_rank || result['造诣'];
                result['所作'] = kw_act || result['所作'];
                result['风评'] = kw_quote || result['风评'];
                result['见效'] = kw_effect || result['见效'];
                return result;
            }

            /* 次选：AI 省去关键词时，按顺序提取中括号内容 */
            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var m;
            while ((m = bracketReg.exec(messageText)) !== null) {
                if (m[1] && m[1].trim()) {
                    brackets.push(m[1].trim());
                }
            }
            if (brackets.length >= 6) {
                result['百艺名称'] = brackets[0];
                result['百艺图标'] = brackets[1];
                result['造诣'] = brackets[2];
                result['所作'] = brackets[3];
                result['风评'] = brackets[4];
                result['见效'] = brackets[5];
            }
            return result;
        }

        /* ========== 百艺图标映射 ========== */
        function getIcon(name) {
            var map = {
                '琴': '🪕', '棋': '⚫', '书': '🖌️', '画': '🖼️',
                '医': '🫙', '毒': '☠️', '卜': '🐢', '易容': '🪭',
