                '厨': '🍲', '唱戏': '🎭', '说书': '📖', '驯兽': '🐅'
            };
            return map[name] || '❖';
        }

        /* ========== 渲染界面（总是渲染，数据缺失用默认值） ========== */
        function renderPage(data, rawText,_el) {
            var name = data['百艺名称'] || '百艺';
