        (function() {

        /* ========== 获取消息内容（宽容：API 失败不崩溃） ========== */
        function getMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (chatMessages && chatMessages.length > 0) {
                    return chatMessages[0].message;
                }
            } catch (e) {
                console.error("获取消息API失败", e);
            }
            return null;
        }

        /* ========== 终极宽容解析（不依赖标签完整性，支持全角符号） ========== */
        function parseData(messageText) {
            var result = {};

            /* 优先在 <breakthrough_panel> 标签内提取；标签缺失则全文兜底 */
            var scope = messageText;
            var tagMatch = messageText.match(/<breakthrough_panel>([\s\S]*?)<\/breakthrough_panel>/);
            if (tagMatch && tagMatch[1]) {
                scope = tagMatch[1];
            }

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            /* 按关键词匹配：支持 [突破阶段|六升七] / 突破阶段：六升七 / 突破阶段:六升七 */
            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    var val = match[1].trim();
                    return val.replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var kw_stage = extractValue('突破阶段');
            var kw_proc = extractValue('破关经过');
            var kw_omen = extractValue('天兆');
            var kw_quote = extractValue('评语');
            var kw_effect = extractValue('突破获益');

            if (kw_stage || kw_proc || kw_effect) {
                if (kw_stage) result['突破阶段'] = kw_stage;
                if (kw_proc) result['破关经过'] = kw_proc;
                if (kw_omen) result['天兆'] = kw_omen;
                if (kw_quote) result['评语'] = kw_quote;
                if (kw_effect) result['突破获益'] = kw_effect;
                return result;
            }

            /* 次选：AI 省去关键词时按顺序提取中括号内容 */
            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var bm;
            while ((bm = bracketReg.exec(scope)) !== null) {
                if (bm[1] && bm[1].trim()) {
                    brackets.push(bm[1].trim());
                }
            }
            if (brackets.length >= 4) {
                result['突破阶段'] = brackets[0];
                result['破关经过'] = brackets[1];
                result['天兆'] = brackets[2];
                result['评语'] = brackets[3];
                if (brackets.length >= 5) result['突破获益'] = brackets[4];
            }
            return result;
        }

