            { keys: ['破景', '景'], name: '大放光明', icon: '☀️', level: '五境八关 · 第六关「景」' },
            { keys: ['破死', '死'], name: '向死而生', icon: '🌘', level: '五境八关 · 第七关「死」' },
            { keys: ['破惊', '惊'], name: '石破天惊', icon: '⚡', level: '五境八关 · 第八关「惊」' },
            { keys: ['入海六关', '六关入海', '六关气海_初入'], name: '六关入海', icon: '🌊', level: '六关气海_初入 · 真气液化 汪洋初成' },
            { keys: ['六关初入升中凝', '六关升中凝', '六关气海_中凝'], name: '中凝有序', icon: '💧', level: '六关气海_中凝 · 液海凝稠 运行有序' },
            { keys: ['六关中凝升满盈', '六关升满盈', '六关气海_满盈'], name: '满盈如海', icon: '🌕', level: '六关气海_满盈 · 汪洋满盈 冲丹之姿' },
            { keys: ['入海七关', '七关入海', '七关气海_初入'], name: '七关入海', icon: '🌊', level: '七关气海_初入 · 真气液化 汪洋初成' },
