                    _el.innerHTML =
                        '<div class="breakthrough-container" style="padding:30px 16px;"><div class="loading">❌ 引气失败：' + error.message + '</div></div>';
                }
            }, 100); /* 增加极微小的延迟，确保 DOM 和酒馆消息体已完全同步 */
        }

        $(function() { document.querySelectorAll('.bt-content').forEach(function(_el) { init(_el); }); });;

        })();
    </script>
