    <div class="found-container found-content" >
        <div class="loading">凿石刻匾中...</div>
    </div>

    <script>
        /* IIFE 作用域隔离：防止多个美化并存时同名函数互相覆盖 */
        (function() {

        /* ========== 获取消息内容（宽容：API 失败不崩溃） ========== */
        function getMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (chatMessages && chatMessages.length > 0) {
                    return chatMessages[0].message;
                }
            } catch (e) {
                console.error("获取消息API失败", e);
            }
            return null;
        }

        /* ========== 终极宽容解析（不依赖标签完整性，支持全角符号） ========== */
        function parseData(messageText) {
            var result = {};

            var scope = messageText;
            var tagMatch = messageText.match(/<sect_found_panel>([\s\S]*?)<\/sect_found_panel>/);
            if (tagMatch && tagMatch[1]) {
                scope = tagMatch[1];
            }

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    var val = match[1].trim();
                    return val.replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var kw_name = extractValue('门派名号');
            var kw_slogan = extractValue('门派宗旨');
            var kw_rank = extractValue('立派规模');
            var kw_founder = extractValue('立派境界');
            var kw_steps = extractValue('立派四步');
            var kw_basis = extractValue('立派经过');
            var kw_bless = extractValue('江湖贺词');
            var kw_stand = extractValue('立足之势');

            if (kw_name || kw_basis || kw_stand) {
                if (kw_name) result['门派名号'] = kw_name;
                if (kw_slogan) result['门派宗旨'] = kw_slogan;
                if (kw_rank) result['立派规模'] = kw_rank;
                if (kw_founder) result['立派境界'] = kw_founder;
                if (kw_steps) result['立派四步'] = kw_steps;
                if (kw_basis) result['立派经过'] = kw_basis;
                if (kw_bless) result['江湖贺词'] = kw_bless;
                if (kw_stand) result['立足之势'] = kw_stand;
                return result;
            }

            /* 次选：按顺序提取中括号内容 */
            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var bm;
            while ((bm = bracketReg.exec(scope)) !== null) {
                if (bm[1] && bm[1].trim()) {
                    brackets.push(bm[1].trim());
                }
            }
            if (brackets.length >= 4) {
                result['门派名号'] = brackets[0];
                result['门派宗旨'] = brackets[1];
                result['立派规模'] = brackets[2];
                result['立派经过'] = brackets[3];
                if (brackets.length >= 5) result['江湖贺词'] = brackets[4];
                if (brackets.length >= 6) result['立足之势'] = brackets[5];
            }
            return result;
        }

        /* ========== 立派规模查表（固定四步） ========== */
        var STEPS_DEFAULT = ['选址立基', '定名立号', '广撒英雄帖', '立规收徒'];

        function parseSteps(stepsText) {
            if (!stepsText) return STEPS_DEFAULT;
            var arr = stepsText.split(/[/／、,，]/);
            var cleaned = [];
            for (var i = 0; i < arr.length; i++) {
                var s = arr[i].trim();
                if (s) cleaned.push(s);
            }
            return cleaned.length >= 2 ? cleaned.slice(0, 6) : STEPS_DEFAULT;
        }

        /* ========== 渲染 ========== */
        function renderPage(data,_el) {
            var name = data['门派名号'] || '未定名';
            var slogan = data['门派宗旨'] || '';
            var rank = data['立派规模'] || '小型门派';
            var founder = data['立派境界'] || '';
            var steps = parseSteps(data['立派四步']);
            var basis = data['立派经过'] || '未见过程。';
            var bless = data['江湖贺词'] || '江湖反响平平。';
            var stand = data['立足之势'] || '未见之势。';

            var speaker = '', blessText = bless;
            var colonIdx = bless.indexOf('：');
            if (colonIdx === -1) colonIdx = bless.indexOf(':');
            if (colonIdx > 0) {
                speaker = bless.substring(0, colonIdx);
                blessText = bless.substring(colonIdx + 1);
            }

            var stepsHtml = '';
            for (var i = 0; i < steps.length; i++) {
                stepsHtml += '<div class="step"><div class="step-num">' + (i + 1) + '</div><div class="step-name">' + steps[i] + '</div></div>';
            }

            var html = `
                <div class="stone-vein sv-1"></div>
                <div class="stone-vein sv-2"></div>
                <div class="cloud cloud-l">☁</div>
                <div class="cloud cloud-r">☁</div>

                <div class="content">
                    <div class="top-tag">山 门 奠 基</div>

                    <div class="stone-plaque">
                        <div class="sect-name">${name}</div>
                        <div class="sect-slogan">${slogan}</div>
                    </div>

                    <div class="meta-row">
                        <div class="meta-chip"><b>规模</b>${rank}</div>
                        <div class="meta-chip"><b>立派</b>${founder}</div>
                    </div>

                    <div class="steps">
                        ${stepsHtml}
                    </div>

                    <div class="proc-box">
                        <span class="proc-label">立派经过</span>${basis}
                    </div>

                    <div class="bless-box">
                        <span class="bless-label">江湖贺词</span>
                        <span class="bless-speaker">${speaker}</span><span class="bless-text">${blessText}</span>
                    </div>

                    <div class="stand-box">
                        <span class="stand-label">立足之势</span>${stand}
                    </div>
                </div>
            `;
            _el.innerHTML = html;
        }

        /* ========== 主函数（延迟确保消息体同步） ========== */
        function init(_el) {
            setTimeout(function() {
                try {
                    var messageText = getMessageData();
                    if (!messageText) {
                        _el.innerHTML =
                            '<div class="found-container" style="padding:30px 16px;"><div class="loading">❌ 无法获取消息内容，请稍后再试</div></div>';
                        return;
                    }
                    var data = parseData(messageText);
                    renderPage(data, _el);
                } catch (error) {
                    console.error("错误:", error);
                    _el.innerHTML =
                        '<div class="found-container" style="padding:30px 16px;"><div class="loading">❌ 凿石失败：' + error.message + '</div></div>';
                }
            }, 100); /* 增加极微小的延迟，确保 DOM 和酒馆消息体已完全同步 */
        }

        $(function() { document.querySelectorAll('.found-content').forEach(function(_el) { init(_el); }); });;

        })();
    </script>
</body>
</html>
