<body>
    <div class="love-container love-date love-content" >
        <div class="loading">铺纸研墨中...</div>
    </div>

    <script>
        /* IIFE 作用域隔离：防止多个美化并存时同名函数互相覆盖 */
        (function() {

        /* ========== 获取消息内容（宽容：API 失败不崩溃） ========== */
        function getMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (chatMessages && chatMessages.length > 0) {
                    return chatMessages[0].message;
                }
            } catch (e) {
                console.error("获取消息API失败", e);
            }
            return null;
        }

        /* ========== 终极宽容解析（不依赖标签完整性，支持全角符号） ========== */
        function parseData(messageText) {
            var result = {};

            var scope = messageText;
            var tagMatch = messageText.match(/<love_panel>([\s\S]*?)<\/love_panel>/);
            if (tagMatch && tagMatch[1]) {
                scope = tagMatch[1];
            }

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    var val = match[1].trim();
                    return val.replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var kw_type = extractValue('剧情类别');
            var kw_a = extractValue('第一人');
            var kw_b = extractValue('第二人');
            var kw_scene = extractValue('场景经过');
            var kw_vow = extractValue('情话誓言');
            var kw_token = extractValue('信物聘礼');
            var kw_block = extractValue('门第阻力');
            var kw_gift = extractValue('聘礼嫁妆');
            var kw_talk = extractValue('旁人反响');
            var kw_rites = extractValue('六礼流程');

            if (kw_type || kw_scene || kw_vow) {
                if (kw_type) result['剧情类别'] = kw_type;
                if (kw_a) result['第一人'] = kw_a;
                if (kw_b) result['第二人'] = kw_b;
                if (kw_scene) result['场景经过'] = kw_scene;
                if (kw_vow) result['情话誓言'] = kw_vow;
                if (kw_token) result['信物聘礼'] = kw_token;
                if (kw_block) result['门第阻力'] = kw_block;
                if (kw_gift) result['聘礼嫁妆'] = kw_gift;
                if (kw_talk) result['旁人反响'] = kw_talk;
                if (kw_rites) result['六礼流程'] = kw_rites;
                return result;
            }

            /* 次选：按顺序提取中括号内容 */
            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var bm;
            while ((bm = bracketReg.exec(scope)) !== null) {
                if (bm[1] && bm[1].trim()) {
                    brackets.push(bm[1].trim());
                }
            }
            if (brackets.length >= 3) {
                result['剧情类别'] = brackets[0];
                result['第一人'] = brackets[1];
                result['第二人'] = brackets[2];
                if (brackets.length >= 4) result['场景经过'] = brackets[3];
                if (brackets.length >= 5) result['情话誓言'] = brackets[4];
            }
            return result;
        }

        /* ========== 剧情类别查表（固定配色/饰徽/主副标题） ========== */
        var TYPE_MAP = [
            { keys: ['花前月下', '约会', '游玩', '踏青', '同行'], cls: 'love-date', seal: '缘', main: '花前月下', sub: '约会' },
            { keys: ['私定', '山盟', '定情', '海誓'], cls: 'love-vow', seal: '誓', main: '山盟海誓', sub: '私定终身' },
            { keys: ['明媒', '成婚', '大婚', '拜堂', '六礼', '迎娶'], cls: 'love-wed', seal: '囍', main: '六礼成婚', sub: '明媒正娶' }
        ];

        function matchType(typeText) {
            var s = typeText || '';
            for (var i = 0; i < TYPE_MAP.length; i++) {
                for (var k = 0; k < TYPE_MAP[i].keys.length; k++) {
                    if (s.indexOf(TYPE_MAP[i].keys[k]) >= 0) {
                        return TYPE_MAP[i];
                    }
                }
            }
            return TYPE_MAP[0];
        }

        /* ========== 渲染 ========== */
        function renderPage(data,_el) {
            var type = matchType(data['剧情类别']);
            var nameA = data['第一人'] || '某';
            var nameB = data['第二人'] || '某';
            var scene = data['场景经过'] || '未见场景。';
            var vow = data['情话誓言'] || '';
            var token = data['信物聘礼'] || '';
            var block = data['门第阻力'] || '';
            var gift = data['聘礼嫁妆'] || '';
            var talk = data['旁人反响'] || '';
            var rites = data['六礼流程'] || '';

            /* 六礼流程条 */
            var ritesArr = [];
            if (Array.isArray(rites)) ritesArr = rites;
            else if (typeof rites === 'string' && rites) ritesArr = rites.split(/[/／、,，]/).map(s => s.trim()).filter(s => s);
            var ritesHtml = '';
            if (ritesArr.length >= 2) {
                ritesHtml = '<div class="rites">';
                for (var i = 0; i < ritesArr.length; i++) {
                    ritesHtml += '<div class="rite"><div class="rite-dot"></div><div class="rite-name">' + ritesArr[i] + '</div></div>';
                }
                ritesHtml += '</div>';
            }

            /* 右列栏目 */
            var rightHtml = '';
            if (ritesHtml) rightHtml += ritesHtml;
            if (vow) rightHtml += '<div class="vow-field">' + vow + '</div>';
            if (token) rightHtml += '<div class="mini-field"><span class="mini-label">信物</span>' + token + '</div>';
            if (block) rightHtml += '<div class="mini-field"><span class="mini-label">阻力</span>' + block + '</div>';
            if (gift) rightHtml += '<div class="mini-field"><span class="mini-label">聘礼嫁妆</span>' + gift + '</div>';
            if (talk) {
                var speaker = '', talkText = talk;
                var ci = talk.indexOf('：');
                if (ci === -1) ci = talk.indexOf(':');
                if (ci > 0) { speaker = talk.substring(0, ci); talkText = talk.substring(ci + 1); }
                rightHtml += '<div class="talk-box"><span class="talk-speaker">' + speaker + '</span><span class="talk-text">' + talkText + '</span></div>';
            }

            var html = `
                <div class="curtain curtain-l"></div>
                <div class="curtain curtain-r"></div>
                <div class="dark-motif"></div>
                <div class="top-seal">${type.seal}</div>
                <div class="corner-flower cf-tl"></div>
                <div class="corner-flower cf-tr"></div>
                <div class="motif-deco butterfly bf-1">🦋</div>
                <div class="motif-deco butterfly bf-2">🦋</div>
                <div class="motif-deco lantern la-1">🏮</div>
                <div class="motif-deco lantern la-2">🏮</div>
                <div class="motif-deco branch-deco br-1">🌸</div>
                <div class="motif-deco branch-deco br-2">🌸</div>

                <div class="content">
                    <div class="top-frieze"></div>
                    <div class="head-row">
                        <div class="type-tag">
                            <span class="t-main">${type.main}</span>
                            <span class="t-sub">${type.sub}</span>
                        </div>
                        <div class="couple">${nameA}<span class="and">·</span>${nameB}</div>
                    </div>

                    <div class="main-grid">
                        <div class="scene-box">
                            <span class="scene-label">场景</span>${scene}
                        </div>
                        <div class="right-col">
                            ${rightHtml}
                        </div>
                    </div>
                </div>
            `;

            var el = _el;
            el.className = 'love-container ' + type.cls;
            el.innerHTML = html;
        }

        /* ========== 主函数（延迟确保消息体同步） ========== */
        function init(_el) {
            setTimeout(function() {
                try {
                    var messageText = getMessageData();
                    if (!messageText) {
                        _el.innerHTML =
                            '<div class="love-container" style="padding:30px 16px;"><div class="loading">❌ 无法获取消息内容，请稍后再试</div></div>';
                        return;
                    }
                    var data = parseData(messageText);
                    renderPage(data, _el);
                } catch (error) {
                    console.error("错误:", error);
                    _el.innerHTML =
                        '<div class="love-container" style="padding:30px 16px;"><div class="loading">❌ 铺纸失败：' + error.message + '</div></div>';
                }
            }, 100); /* 增加极微小的延迟，确保 DOM 和酒馆消息体已完全同步 */
        }

        $(function() { document.querySelectorAll('.love-content').forEach(function(_el) { init(_el); }); });;

        })();
    </script>
</body>
</html>
