            if (tagMatch && tagMatch[1]) { scope = tagMatch[1]; }

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    return match[1].trim().replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
