function dlhNativeNarrativeView(input) {
  if(input===undefined)return {状态:'当前存档尚不可读，禁止猜写缺失事实'};
  const view=JSON.parse(JSON.stringify(input));
  const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
  const drop=(o,keys)=>{if(object(o))for(const k of keys)delete o[k];};
  const values=o=>object(o)?Object.values(o):[];
  // Current NPC values and pending/errors stay visible; settled receipts are bookkeeping.
  drop(view.系统接入,['已办','好感']);
  // Narrative receives public capabilities, never the executable definition.
  // Full definitions remain in the actual MVU and dedicated generation inputs.
  const art=a=>{
    if(!object(a))return;
    const definition=a.战斗定义?.内容||a.战斗定义;
    if(Array.isArray(definition?.moves))a.已定义招式=definition.moves.map(m=>({名称:m.name||m.名称,解锁:m.tier||m.熟练度,...(m.description||m.desc?{说明:m.description||m.desc}:{})}));
    drop(a,['战斗定义']);
  };
  const gear=g=>{if(!object(g))return;drop(g,['面板加成','境界词条','精锻基准','原文指纹']);};
  const npc=n=>{
    if(!object(n))return;
    if(Array.isArray(n.武学表))n.武学表.forEach(art);
    drop(n,['建档配置','装备模板记录']);
    Object.entries(n.装备栏||{}).filter(([key])=>key!=='装备库').forEach(([,g])=>gear(g));
  };
  const h=view?.主角,w=view?.世界;
  if(object(h)) {
    drop(h.星命传承,['records','draw','nurture','battleReceipts']);
    drop(h.灵木培育,['请求','管控物品','已养护日']);
    drop(h.武学成长,['基准','账本','派生','来源历史','来源已初始化','每日训练']);
    drop(h.感悟成长,['基准','定义','账本','取值缓存','快照','百艺基准','百艺每日','见闻基准','心性基准']);
    drop(h.境界修行,['种子','账本','机缘快照','训练快照','阶段七窍基准','阶段养窍基准','阶段五脏基准']);
    values(h.武学与意境面板?.掌握武学).forEach(art);
    values(h.武学与意境面板?.领悟之意).forEach(art);
    for(const row of values(h.天赋体质)){
      if(!object(row))continue;
      const definition=row.能力定义?.内容||row.战斗定义?.内容;
      if(Array.isArray(definition?.招式))row.已定义招式=definition.招式.map(m=>({名称:m.name||m.名称,说明:m.description||m.desc||m.说明||''}));
      if(Array.isArray(definition?.成长方案))row.成长条件=definition.成长方案.map(p=>({阶段:p.阶段,条件:p.条件}));
      if(definition?.战斗悟学)row.悟学条件=JSON.parse(JSON.stringify(definition.战斗悟学));
      drop(row,['能力定义','战斗定义','定义记录']);
    }
    Object.entries(h.装备栏||{}).filter(([key])=>key!=='装备库').forEach(([,g])=>gear(g));
    values(h.装备栏?.装备库).forEach(gear);
    const p=h.战斗面板;
    drop(p,['基础基准','基础烘焙','资源缺口','上次资源']);
    drop(p,['基础属性','生效属性','常驻增益','装配被动','属性来源','三率来源']);
    drop(p?.日常恢复,['记录','余量']);
    // Drug use counts and active durations are gameplay constraints, not cache.
    drop(p?.消耗品,['已结算战斗']);
    DLH_CRAFTING_NARRATIVE.project(input,view);
  }
  if(object(w)) {
    drop(w,['正文回传','正文承接']);
    if(object(w.NPC战斗档案))w.已知战斗余量=Object.fromEntries(Object.entries(w.NPC战斗档案).map(([id,r])=>[id,{名称:r?.配置?.名称,境界:r?.配置?.境界,生死:r?.配置?.生死,...(object(r?.状态)?JSON.parse(JSON.stringify(r.状态)):{}),最近战斗:r?.最近战斗}]));
    drop(w,['武学战斗定义库','NPC生成记录','NPC战斗档案']);
    drop(w.日历,['消息处理']);
    for(const a of values(w.日历?.活动))drop(a,['指纹']);
    const pending=new Set(w.日历?.待叙述||[]);
    if(object(w.日历?.活动))for(const key of Object.keys(w.日历.活动))if(!pending.has(key))delete w.日历.活动[key];
    if(object(w.时间记录))for(const key of Object.keys(w.时间记录))if(input?.世界?.日历?.活动?.[key])delete w.时间记录[key];
    for(const m of values(w.同行?.成员))drop(m,['邀约指纹']);
  }
  for(const bs of [view?.战斗状态,h?.战斗状态]) {
    drop(bs,['引擎存档','随机种子']);
    npc(bs?.敌方);
    for(const list of [bs?.我方队友,bs?.敌方队伍])if(Array.isArray(list))list.forEach(npc);
    // Keep all unacknowledged battle facts. A sent transcript is already in
    // message history; result/epilogue/participants/resources stay visible.
    if(object(bs)&&bs.阶段!=='进行中'&&bs.战报已发送===true)drop(bs,['战报','事件流']);
  }
  return view;
}



