roved"}]},{"name":"玛尔法","kind":"芳闻","publicName":"玛尔法","enabled":true,"public":true,"province":"罗刹国","scope":"罗刹国","rumors":[{"id":"芳闻-玛尔法-1","ordinal":1,"text":"冻河泊的歇脚酒肆里，几个猎户正瞧着墙角那位眉淡面白的妇人。她穿着利落的灰白翻毛短袄，腰挎两柄雪色短刀，眼下正就着一盘干肉小口抿烈酒，半句闲话也不多说。","status":"approved"},{"id":"芳闻-玛尔法-2","ordinal":2,"text":"寒林镇大集边的马具铺外，那位短袄袖口扎紧的利落妇人正站在那儿。掌柜正按她的要求加固皮带扣子，她腰挎两把雪白短刀，抱着胳膊在一旁静静盯着工匠手艺。","status":"approved"},{"id":"芳闻-玛尔法-3","ordinal":3,"text":"碎冰关南面茶水摊的伙计念叨，有个面色寡淡的妇人正坐在长凳上歇脚。她腰间插着两把白晃晃的短刀，这会儿正拿粗布细细擦拭雪地靴上的泥浆，动作格外麻利。","status":"approved"},{"id":"芳闻-玛尔法-4","ordinal":4,"text":"白石城城门外的铁匠棚前，围着看热闹的人说那位眉眼寡淡的妇人正等铁料冷却。她一身灰白短袄，正抱臂倚着炉台，等着铁匠替她换新打好的防滑冰爪。","status":"approved"}]},{"name":"幽夫人","kind":"芳闻","publicName":"幽夫人","enabled":true,"public":true,"province":"蓬莱","scope":"蓬莱","rumors":[{"id":"芳闻-幽夫人-1","ordinal":1,"text":"瀛洲集市南街的药材铺掌柜正忙着赔笑，幽夫人这会儿黑纱覆面坐在铺内，垂眸翻看刚从深海采来的几株墨色毒珊瑚，周遭隐隐飘着甜腻异香，连路过的采药客都不敢大声喘气。","status":"approved"},{"id":"芳闻-幽夫人-2","ordinal":2,"text":"蓬莱岛深海采集场的栈桥边聚了不少船工，幽夫人身着奇异苗疆衣裙站在那儿，正由侍从端着瓷盅，亲手辨验几尾刚从深水捞起的斑斓海蛇，眼下谁也不敢近前打扰。","status":"approved"},{"id":"芳闻-幽夫人-3","ordinal":3,"text":"瀛洲主港的香料行门前微风送香，幽夫人今日正立在柜台前挑选南洋送来的干草药，指尖轻捻香料细细闻嗅，旁边的伙计恭恭敬敬地候着回话，引得不少茶客在门外张望。","status":"approved"},{"id":"芳闻-幽夫人-4","ordinal":4,"text":"方丈岛私港的一处临海茶棚里，幽夫人正倚在竹榻上漫不经心地品着凉茶，黑纱微动，目光落向外头货船卸下的几个大药箱，随行侍女正拿着账册在桌前向她轻声禀报。","status":"approved"}]},{"name":"阿朵骨","kind":"芳闻","publicName":"阿朵骨","enabled":true,"public":true,"province":"南疆","scope":"南疆","rumors":[{"id":"芳闻-阿朵骨-1","ordinal":1,"text":"黑水寨的神树石阶下，黑水部的大巫祭阿朵骨这会儿正给求药的族人分发驱虫草包。她颈上盘着那条黑斑大蟒，赤足踩在青石上，正神色温和地替身前的小童点涂雄黄。","status":"approved"},{"id":"芳闻-阿朵骨-2","ordinal":2,"text":"听采药的苗人说，阿朵骨大巫祭眼下正在百族药谷的石坊前挑拣药材。她身着五彩衣裳，正一边逗弄腕间的毒虫，一边同药农仔细比对刚采下来的几篓新鲜药草。","status":"approved"},{"id":"芳闻-阿朵骨-3","ordinal":3,"text":"雾瘴关的互市木楼边热闹得很，阿朵骨今日正赤足坐在二楼临街的竹榻上歇息。她脖颈缠着黑斑毒蟒，正垂眸打量楼下中原客商带来的各色干果与布匹。","status":"approved"},{"id":"芳闻-阿朵骨-4","ordinal":4,"text":"黑水寨寨门前的藤桥边，阿朵骨此刻正带着几名巫女检视进寨的背篓。她身前盘着臂粗的毒蟒，正低头核验过桥猎户带回的晒干药材，瞧着十分细致耐烦。","status":"approved"}]},{"name":"薇玛拉","kind":"芳闻","publicName":"薇玛拉","enabled":true,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-薇玛拉-1","ordinal":1,"text":"蒲甘城万塔的石阶前，白衣赤足的薇玛拉正坐在阴凉处，手里拿把小苇帚，帮看塔的老沙弥细细扫除佛龛石缝里的落叶，任凭香客来往也不抬头。","status":"approved"},{"id":"芳闻-薇玛拉-2","ordinal":2,"text":"蒲甘城门外的茶摊底下，那位长发散垂的白衣姑娘薇玛拉眼下正要了一碗清水歇脚，指尖正慢条斯理摩挲着颈上那串缺了木珠的旧链子。","status":"approved"},{"id":"芳闻-薇玛拉-3","ordinal":3,"text":"蒲甘城渡口边的水桥旁，薇玛拉正立在栈板上，替靠岸的采莲小童将一篓篓新鲜水白莲接上岸，整齐码在青石板边，引得过路行人都放慢了步子。","status":"approved"},{"id":"芳闻-薇玛拉-4","ordinal":4,"text":"蒲甘城外市集北头的药草棚前，持经人薇玛拉正驻足挑选驱热的苦草根，摊贩给她递过洗净的叶包，她正安静站在摊前等候称量。","status":"approved"}]},{"name":"阿玛雅","kind":"芳闻","publicName":"阿玛雅","enabled":true,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-阿玛雅-1","ordinal":1,"text":"巴石河口码头的石阶边，两臂刺满浪纹的阿玛雅正赤足踩在空鱼箱上，腰别两根藤木短棍，扯着嗓门替村里相熟的疍户跟收鱼贩子算账还价呢。","status":"approved"},{"id":"芳闻-阿玛雅-2","ordinal":2,"text":"素万城擂台旁的凉棚里，吕宋村邦的少头人阿玛雅正和几个南洋拳手拼桌，两根短棍横在桌角，她正拍着桌子同众人掷椰子壳赌酒，笑声极响亮。","status":"approved"},{"id":"芳闻-阿玛雅-3","ordinal":3,"text":"巴石河口大集市里的藤编摊前，短棍阿玛雅正叉着腰挑拣结实的藤皮绳，手里短棍上下晃悠着，跟铺子掌柜讨价还价，护短地替同村人多讨了两捆。","status":"approved"},{"id":"芳闻-阿玛雅-4","ordinal":4,"text":"蒲甘城南门外的河埠头边，阿玛雅正带着几个吕宋小伙蹲在栈桥上，手里拿短棍拨弄水里的浮木比试眼力，嘴里还在大声催促着船家快备缆绳。","status":"approved"}]},{"name":"巴月","kind":"芳闻","publicName":"巴月","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-巴月-1","ordinal":1,"text":"附近驿站的马料棚前，那位着短款豹皮装、手臂绘满青纹的巴月姑娘正拿胡萝卜喂驮马。她腰间盘着兽筋长鞭，正跟伙计仔细打听进深山打猎的路径呢。","status":"approved"},{"id":"芳闻-巴月-2","ordinal":2,"text":"街口铁匠铺子外，巴月正蹲在磨石旁试她长鞭上的铜环。她一身兽皮猎装引得不少人张望，她倒浑不在意，正挽着袖子催铁匠赶快给她的猎刀淬火。","status":"approved"},{"id":"芳闻-巴月-3","ordinal":3,"text":"听闻附近野味集市里热闹得很，巴月正扛着两头山鸡跟皮货掌柜讨价还价。她小腿上绘着山熊战纹，说话嗓门极脆，这会儿还在货摊前比划毛皮成色。","status":"approved"},{"id":"芳闻-巴月-4","ordinal":4,"text":"镇外老槐树下的茶摊边，巴月正踩着长凳喝大碗酽茶，随身的兽筋长鞭搭在桌角。邻桌的几个老猎户正跟她讨教鞣皮子的窍门，她聊得兴起，眼下还没打算动身。","status":"approved"}]},{"name":"蓝鸯","kind":"芳闻","publicName":"蓝鸯","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-蓝鸯-1","ordinal":1,"text":"镇子水井旁的凉棚下，叮叮当当一阵银饰脆响，原是蓝鸯姑娘正教几个孩童翻花绳。她腕上挂满精致小银铃，笑声清脆，这会儿正从兜里抓糖果分给大家。","status":"approved"},{"id":"芳闻-蓝鸯-2","ordinal":2,"text":"附近草药铺子前，一身苗银叮当晃动的蓝鸯正挑拣掌柜新晒的草药。她生得古灵精怪，偏爱辨认那些带刺的古怪根茎，这会儿还在跟药铺伙计磨蹭着要买整筐。","status":"approved"},{"id":"芳闻-蓝鸯-3","ordinal":3,"text":"渡口边上的糖画摊子前围了不少人，那位叫蓝鸯的苗服姑娘正晃着满头银饰等她的糖兔子。转盘恰好转到了金凤，她乐得直拍手，催着摊贩快些浇糖浆。","status":"approved"},{"id":"芳闻-蓝鸯-4","ordinal":4,"text":"街心小酒馆的二楼窗边，蓝鸯正托着下巴看街景，身上的银饰随着动作闪闪发亮。她桌上摆着几碟甜渍酸梅，正一边剥花生一边冲楼下路过的杂耍班子挥手。","status":"approved"}]},{"name":"商镜寒","kind":"芳闻","publicName":"商镜寒","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-商镜寒-1","ordinal":1,"text":"附近客栈的大堂角落里，一身深色短袍的商镜寒正独自就着清水嚼面饼。这位年轻人神情格外沉静，随身的行囊搁在脚边，似乎正坐着等同行的脚夫结账。","status":"approved"},{"id":"芳闻-商镜寒-2","ordinal":2,"text":"镇外旧牌坊下的茶棚里，商镜寒正坐着歇凉。她面容冷峻、话极少，旁人上前问路她也只微微颔首，眼下正慢条斯理地用软布擦拭护腕上的尘土。","status":"approved"},{"id":"芳闻-商镜寒-3","ordinal":3,"text":"集市书摊前，被称为墨雷的商镜寒正翻阅几本地志残卷。她神色专注，指节轻敲着书页，正向摊主打听附近荒岭残冢的去向，暂时还没离开摊前。","status":"approved"},{"id":"芳闻-商镜寒-4","ordinal":4,"text":"附近古桥的青石栏杆旁，商镜寒正负手观望桥下流水。她周身气度内敛，几个行脚僧路过合十行礼，她也客气回了一礼，眼下仍在桥头迎风静立。","status":"approved"}]},{"name":"白悟","kind":"芳闻","publicName":"白悟","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-白悟-1","ordinal":1,"text":"附近告示栏底下，白发蓝眸的散客白悟正仰头扯下一张除盗榜文。她一身粗布短打，利落地卷着袖口，正爽快地跟巡街差役核对赏银，这会儿正往怀里揣回执凭证。","status":"approved"},{"id":"芳闻-白悟-2","ordinal":2,"text":"镇口面摊前，白悟正稀里哗啦大口吃着臊子面，一头白发束得利落。她边吃边向面摊掌柜打听附近有没有油腔滑调的游方道士，看来还得再坐上一碗面的工夫。","status":"approved"}]},{"name":"秦施思","kind":"芳闻","publicName":"秦施思","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-秦施思-1","ordinal":1,"text":"附近大榕树下的卦摊前，游方术士秦施思正摇着幌子给人摸骨看相。她三寸不烂之舌极是厉害，把对面的行商说得连连点头，这会儿正乐呵呵地把卦金往袖里收。","status":"approved"},{"id":"芳闻-秦施思-2","ordinal":2,"text":"巷口茶馆里，秦施思正倚在柜台边与武林盟的信差勾肩搭背套近乎。她一身半旧道袍，满脸堆笑，正悄悄打听哪条出镇的路没白发散客把守，手里的茶碗还没放下。","status":"approved"}]},{"name":"凌寒舞","kind":"芳闻","publicName":"凌寒舞","enabled":true,"public":true,"province":"跨域池","scope":"跨域池","rumors":[{"id":"芳闻-凌寒舞-1","ordinal":1,"text":"听村口布庄的伙计讲，那位白发蓝眸的凌寒舞姑娘正站在铺子前挑新裁的云纹罗裙呢。嘴上直挑剔料子不够轻软